"""Plot bitrate/PSNR points generated by codec_lab.encoder_matrix."""
from __future__ import annotations
import argparse
from pathlib import Path
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd

def create_rd_plot(csv_path: Path, output: Path) -> Path:
    data = pd.read_csv(csv_path).sort_values("bitrate_kbps")
    required = {"bitrate_kbps", "decoded_video_psnr_db", "crf", "encoder", "preset"}
    missing = required.difference(data.columns)
    if missing:
        raise ValueError(f"CSV is missing required columns: {sorted(missing)}")
    output.parent.mkdir(parents=True, exist_ok=True)
    fig, ax = plt.subplots(figsize=(8.5, 5.0))
    ax.plot(data["bitrate_kbps"], data["decoded_video_psnr_db"], marker="o")
    for _, row in data.iterrows():
        ax.annotate(f"CRF {int(row['crf'])}", (row["bitrate_kbps"], row["decoded_video_psnr_db"]),
                    xytext=(5, 5), textcoords="offset points", fontsize=8)
    first = data.iloc[0]
    ax.set_title(f"Rate–distortion points: {first['encoder']} / {first['preset']}")
    ax.set_xlabel("Encoded bitrate (kb/s; container size / source duration)")
    ax.set_ylabel("Decoded-video PSNR vs input (dB)")
    ax.grid(alpha=0.25)
    fig.tight_layout()
    fig.savefig(output, dpi=160)
    plt.close(fig)
    return output

def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("csv", type=Path, nargs="?", default=Path("results/encoder_rd.csv"))
    parser.add_argument("--output", type=Path, default=Path("results/encoder_rd_curve.png"))
    args = parser.parse_args()
    print(create_rd_plot(args.csv, args.output))

if __name__ == "__main__":
    main()
